import java.util.Scanner;

public class Main {
    static long recursive(long n, int pos, long[] base) {
        long total = (long)(pos + 1) * (n / base[pos]);
        n %= base[pos];
        if (n == 0) return total;
        long option1 = recursive(n, pos - 1, base);
        long option2 = pos + 1 + recursive(base[pos] - n, pos - 1, base);
        return total + Math.min(option1, option2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long[] a = new long[16];
        a[0] = 1;
        for (int i = 1; i < 16; ++i) {
            a[i] = a[i - 1] * 10 + 1;
        }
        long n = sc.nextLong();
        System.out.println(recursive(n, 15, a));
        sc.close();
    }
}
